-- 105: Original BrillaPrep 4MA1 beta questions, part 1.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_001', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A laptop priced at GHS 2,400 is reduced by 15%. Calculate the sale price.', 'multiple_choice', '["A. GHS 2,040","B. GHS 2,385","C. GHS 2,160","D. GHS 2,760"]', 'A', 'Fifteen percent of 2,400 is 360, so subtracting the discount gives 2,400 − 360 = 2,040. Therefore the correct answer is A: GHS 2,040.', 'easy', 1, 1, 90, 'st_edx_4ma1_num', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_002', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Share GHS 840 in the ratio 3:4. What is the larger share?', 'multiple_choice', '["A. GHS 360","B. GHS 480","C. GHS 420","D. GHS 560"]', 'B', 'There are seven equal parts; each is 840 ÷ 7 = 120, and the larger share is 4 × 120 = 480. Therefore the correct answer is B: GHS 480.', 'medium', 2, 2, 90, 'st_edx_4ma1_num', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_003', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Write 0.000672 in standard form.', 'multiple_choice', '["A. 6.72 × 10⁻³","B. 67.2 × 10⁻⁴","C. 6.72 × 10⁻⁴","D. 0.672 × 10⁻⁴"]', 'C', 'Move the decimal point four places right to obtain 6.72, so the compensating power is 10 to the power −4. Therefore the correct answer is C: 6.72 × 10⁻⁴.', 'hard', 1, 1, 90, 'st_edx_4ma1_num', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_004', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A length is 8.4 cm correct to the nearest 0.1 cm. What is its upper bound?', 'multiple_choice', '["A. 8.35 cm","B. 8.40 cm","C. 8.50 cm","D. 8.45 cm"]', 'D', 'Half of the rounding unit 0.1 is 0.05, so the interval ends just below 8.45 cm and its upper bound is 8.45 cm. Therefore the correct answer is D: 8.45 cm.', 'easy', 2, 2, 90, 'st_edx_4ma1_num', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_005', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Calculate 3/5 + 7/10 and give the answer in simplest form.', 'multiple_choice', '["A. 13/10","B. 10/15","C. 1","D. 7/15"]', 'A', 'Convert 3/5 to 6/10, then add 6/10 + 7/10 = 13/10, which is already in simplest fractional form. Therefore the correct answer is A: 13/10.', 'medium', 3, 3, 90, 'st_edx_4ma1_num', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_006', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A population rises from 12,000 to 13,500. Calculate the percentage increase.', 'multiple_choice', '["A. 11.1%","B. 12.5%","C. 15%","D. 112.5%"]', 'B', 'The increase is 1,500. Dividing by the original 12,000 and multiplying by 100 gives 12.5%. Therefore the correct answer is B: 12.5%.', 'hard', 2, 2, 90, 'st_edx_4ma1_num', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_007', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Evaluate (3.6 × 10⁵) ÷ (1.2 × 10²).', 'multiple_choice', '["A. 3 × 10⁷","B. 0.3 × 10³","C. 3 × 10³","D. 3 × 10²"]', 'C', 'Divide the coefficients to get 3 and subtract the powers, 5 − 2 = 3, giving 3 × 10³. Therefore the correct answer is C: 3 × 10³.', 'easy', 1, 1, 90, 'st_edx_4ma1_num', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_008', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'The exchange rate is GHS 15.60 to USD 1. How many dollars are received for GHS 1,248?', 'multiple_choice', '["A. USD 79","B. USD 81","C. USD 1,263.60","D. USD 80"]', 'D', 'Divide the cedi amount by the cedi-per-dollar rate: 1,248 ÷ 15.60 = 80 dollars. Therefore the correct answer is D: USD 80.', 'medium', 2, 2, 90, 'st_edx_4ma1_num', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_009', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A recipe uses flour and sugar in the ratio 5:2. If 350 g of flour is used, calculate the sugar mass.', 'multiple_choice', '["A. 140 g","B. 70 g","C. 175 g","D. 875 g"]', 'A', 'Each ratio part represents 350 ÷ 5 = 70 g, so sugar requires 2 × 70 = 140 g. Therefore the correct answer is A: 140 g.', 'hard', 1, 1, 90, 'st_edx_4ma1_num', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_010', 'topic_edx_4ma1_num', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Calculate the compound value of GHS 2,000 after two years at 5% per year.', 'multiple_choice', '["A. GHS 2,100","B. GHS 2,205","C. GHS 2,200","D. GHS 2,250"]', 'B', 'Compound growth multiplies by 1.05 each year: 2,000 × 1.05² = 2,205. Therefore the correct answer is B: GHS 2,205.', 'easy', 3, 3, 90, 'st_edx_4ma1_num', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_011', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Solve 5x − 7 = 28.', 'multiple_choice', '["A. x = 4.2","B. x = 5","C. x = 7","D. x = 9"]', 'C', 'Add 7 to both sides to obtain 5x = 35, then divide by 5 to obtain x = 7. Therefore the correct answer is C: x = 7.', 'medium', 1, 1, 90, 'st_edx_4ma1_alg', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_012', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Factorise x² − 9x + 20.', 'multiple_choice', '["A. (x + 4)(x + 5)","B. (x − 2)(x − 10)","C. (x + 4)(x − 5)","D. (x − 4)(x − 5)"]', 'D', 'The required numbers multiply to 20 and add to −9; they are −4 and −5, giving the two factors. Therefore the correct answer is D: (x − 4)(x − 5).', 'hard', 2, 2, 90, 'st_edx_4ma1_alg', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_013', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'The sequence is 7, 11, 15, 19, ... What is its nth term?', 'multiple_choice', '["A. 4n + 3","B. 4n + 7","C. 3n + 4","D. 7n − 3"]', 'A', 'The common difference is 4, so start with 4n; matching the first term requires adding 3. Therefore the correct answer is A: 4n + 3.', 'easy', 1, 1, 90, 'st_edx_4ma1_alg', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_014', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'If f(x) = 3x² − 2, calculate f(−2).', 'multiple_choice', '["A. −14","B. 10","C. −10","D. 34"]', 'B', 'Squaring −2 gives 4; then 3 × 4 − 2 = 12 − 2 = 10. Therefore the correct answer is B: 10.', 'medium', 2, 2, 90, 'st_edx_4ma1_alg', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_015', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Solve the simultaneous equations x + y = 11 and x − y = 3.', 'multiple_choice', '["A. x = 4, y = 7","B. x = 8, y = 3","C. x = 7, y = 4","D. x = 6, y = 5"]', 'C', 'Adding the equations gives 2x = 14, so x = 7; substituting into x + y = 11 gives y = 4. Therefore the correct answer is C: x = 7, y = 4.', 'hard', 3, 3, 90, 'st_edx_4ma1_alg', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_016', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Expand and simplify 3(2x − 5) − 2(x + 1).', 'multiple_choice', '["A. 4x − 13","B. 8x − 17","C. 4x − 7","D. 4x − 17"]', 'D', 'Expanding gives 6x − 15 − 2x − 2; collecting like terms gives 4x − 17. Therefore the correct answer is D: 4x − 17.', 'easy', 2, 2, 90, 'st_edx_4ma1_alg', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_017', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Make r the subject of A = πr².', 'multiple_choice', '["A. r = √(A/π)","B. r = A/π","C. r = √A/π","D. r = π/A²"]', 'A', 'Divide both sides by π to get r² = A/π, then take the positive square root for a radius. Therefore the correct answer is A: r = √(A/π).', 'medium', 1, 1, 90, 'st_edx_4ma1_alg', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_018', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Solve the inequality 2x + 5 < 17.', 'multiple_choice', '["A. x > 6","B. x < 6","C. x < 11","D. x > 11"]', 'B', 'Subtract 5 to get 2x < 12, then divide by positive 2 without reversing the inequality. Therefore the correct answer is B: x < 6.', 'hard', 2, 2, 90, 'st_edx_4ma1_alg', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_019', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'The line has gradient −3 and passes through (0, 5). Which equation represents it?', 'multiple_choice', '["A. y = 3x + 5","B. y = −3x − 5","C. y = −3x + 5","D. y = 5x − 3"]', 'C', 'In y = mx + c, the gradient is m = −3 and the y-intercept from (0, 5) is c = 5. Therefore the correct answer is C: y = −3x + 5.', 'easy', 1, 1, 90, 'st_edx_4ma1_alg', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_020', 'topic_edx_4ma1_alg', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Solve the equation x² = 49.', 'multiple_choice', '["A. x = 7 only","B. x = −7 only","C. x = 24.5","D. x = 7 or x = −7"]', 'D', 'Both 7² and (−7)² equal 49, so a complete solution includes both square roots. Therefore the correct answer is D: x = 7 or x = −7.', 'medium', 3, 3, 90, 'st_edx_4ma1_alg', 'Identify', 'AO2', 'board_edexcel');
